                            Body = "<div style='font-family: sans-serif; padding: 20px; border: 1px solid #eee; border-radius: 10px; max-width: 500px;'><h2 style='color: #2c3e50;'>Verification Code</h2><p>Hello <strong>{{FullName}}</strong> metallic,</p><p>Your security code is:</p><div style='font-size: 24px; font-weight: bold; background: #f8f9fa; padding: 15px; text-align: center; border-radius: 5px; color: #c5a059; border: 1px solid #eee;'>{{OtpCode}}</div><p>Valid for 10 minutes. Do not share this code.</p></div>",
                            Channel = 0,
                            Code = "OTP_EMAIL",
                            Description = "OTP verification email",
                            LastUpdated = new DateTime(2026, 9, 22, 15, 59, 15, 174, DateTimeKind.Utc).AddTicks(9685),
                            Subject = "{{OrgShortName}} Verification Code: {{OtpCode}}",
                            Variables = "['FullName', 'OtpCode']"
                        },
                        new
                        {
                            Id = -2,
                            Body = "<div style='font-family: sans-serif; padding: 20px; border: 1px solid #eee; border-radius: 10px; max-width: 600px;'><h2 style='color: #2c3e50;'>Welcome to {{OrgShortName}}</h2><p>Dear <strong>{{FullName}}</strong>,</p><p>Your membership has been approved! We are excited to have you as part of our community.</p><div style='background: #e8f4fd; padding: 15px; border-radius: 5px; border-left: 4px solid #3498db;'><p><strong>Membership No:</strong> {{MembershipNumber}}</p><p><strong>Default Password:</strong> <code style='background:#fff; padding:2px 5px;'>{{DefaultPassword}}</code></p></div><p>Please log in and change your password immediately.</p></div>",
                            Channel = 0,
                            Code = "WELCOME_EMAIL",
                            Description = "Welcome email",
                            LastUpdated = new DateTime(2026, 9, 22, 15, 59, 15, 176, DateTimeKind.Utc).AddTicks(2185),
                            Subject = "Welcome to {{OrgName}}!",
                            Variables = "['FullName', 'MembershipNumber', 'DefaultPassword']"
                        },
                        new
                        {
                            Id = -3,
                            Body = "<div style='font-family: sans-serif; padding: 20px; border: 1px solid #eee; border-radius: 10px; max-width: 600px;'><h2 style='color: #c5a059;'>Password Reset</h2><p>Hello <strong>{{FullName}}</strong>,</p><p>An administrator has initiated a password reset for your {{OrgShortName}} account. Click below to set a new password — the link is valid for 24 hours.</p><div style='text-align: center; margin: 30px 0;'><a href='{{ResetUrl}}' style='background: #111; color: #c5a059; padding: 12px 30px; text-decoration: none; border-radius: 8px; font-weight: 800; display: inline-block; border: 1px solid #c5a059;'>Reset My Password</a></div><p style='color: #666; font-size: 0.9rem;'>If you did not request this, please ignore this email.</p></div>",
                            Channel = 0,
                            Code = "PASSWORD_RESET",
                            Description = "Password reset email",
                            LastUpdated = new DateTime(2026, 9, 22, 15, 59, 15, 176, DateTimeKind.Utc).AddTicks(2365),
                            Subject = "{{OrgShortName}} Account Password Reset",
                            Variables = "['FullName', 'ResetUrl']"
                        },
                        new
                        {
                            Id = -4,
                            Body = "<div style='font-family: sans-serif; padding: 20px; border: 1px solid #eee; border-radius: 10px; max-width: 600px;'><h2 style='color: #e74c3c;'>Application Status Update</h2><p>Dear <strong>{{FullName}}</strong>,</p><p>Thank you for your interest in the {{OrgName}}. After reviewing your application, we regret to inform you that we cannot approve it at this time.</p><div style='background: #fdf2f2; padding: 15px; border-radius: 5px; border-left: 5px solid #e74c3c;'><p><strong>Reason:</strong> {{Reason}}</p></div><p>If you believe this is an error, please contact the association office.</p></div>",
                            Channel = 0,
                            Code = "APPLICATION_REJECTED",
                            Description = "Application rejection email",
                            LastUpdated = new DateTime(2026, 9, 22, 15, 59, 15, 176, DateTimeKind.Utc).AddTicks(2732),
                            Subject = "Update on your {{OrgShortName}} Membership Application",
                            Variables = "['FullName', 'Reason']"
                        },
                        new
                        {
                            Id = -5,
                            Body = "<div style='font-family: sans-serif; padding: 20px; border: 1px solid #eee; border-radius: 10px; max-width: 600px;'><h2 style='color: #2c3e50;'>Payment Received</h2><p>Dear <strong>{{FullName}}</strong>,</p><p>We have successfully received your payment. It is currently under verification.</p><div style='background: #f8f9fa; padding: 15px; border-radius: 5px;'><p><strong>Amount:</strong> {{Amount}} BDT</p><p><strong>Transaction ID:</strong> {{TrxID}}</p></div><p>You will be notified once the payment is verified.</p></div>",
                            Channel = 0,
                            Code = "PAYMENT_RECEIVED",
                            Description = "Payment received acknowledgment",
                            LastUpdated = new DateTime(2026, 9, 22, 15, 59, 15, 176, DateTimeKind.Utc).AddTicks(2851),
                            Subject = "Payment Received: {{Amount}} BDT",
                            Variables = "['FullName', 'Amount', 'TrxID']"
                        },
                        new
                        {
                            Id = -6,
                            Body = "<div style='font-family: sans-serif; padding: 20px; border: 1px solid #eee; border-radius: 10px; max-width: 600px;'><h2 style='color: #2c3e50;'>Payment Status Update</h2><p>Dear <strong>{{FullName}}</strong>,</p><p>The status of your transaction <strong>{{TrxID}}</strong> has been updated to <strong>{{Status}}</strong>.</p><p>Thank you for your contribution.</p></div>",
                            Channel = 0,
                            Code = "PAYMENT_STATUS_UPDATED",
                            Description = "Payment status update email",
                            LastUpdated = new DateTime(2026, 9, 22, 15, 59, 15, 176, DateTimeKind.Utc).AddTicks(2950),
                            Subject = "Payment Status Updated: {{Status}}",
                            Variables = "['FullName', 'TrxID', 'Status']"
                        },
                        new
                        {
                            Id = -7,
                            Body = "<div style='font-family: sans-serif; padding: 20px; border: 1px solid #eee; border-radius: 10px; max-width: 600px;'><h2 style='color: #2c3e50;'>Family Link Request</h2><p>Hello <strong>{{FullName}}</strong>,</p><p><strong>{{RequesterName}}</strong> has requested to link their account with yours as a <strong>{{Relationship}}</strong>.</p><div style='text-align: center; margin: 30px 0;'><a href='{{ProfileUrl}}' style='background: #c5a059; color: #fff; padding: 12px 30px; text-decoration: none; border-radius: 8px; font-weight: bold; border: 1px solid #c5a059;'>Review Request</a></div><p>Please log in to your profile to accept or decline this request.</p></div>",
                            Channel = 0,
                            Code = "FAMILY_LINK_REQUEST",
                            Description = "Family link request email",
                            LastUpdated = new DateTime(2026, 9, 22, 15, 59, 15, 176, DateTimeKind.Utc).AddTicks(3040),
                            Subject = "New Family Link Request from {{RequesterName}}",
                            Variables = "['FullName', 'RequesterName', 'Relationship', 'ProfileUrl']"
                        },
                        new
